<?php get_header(); ?><main id="content"><section class="saf-section saf-product-detail-section"><div class="saf-container"><?php while(have_posts()): the_post(); $terms=get_the_terms(get_the_ID(),'flower_category'); ?><div class="saf-product-detail"><div class="saf-product-detail-media"><img class="saf-detail-image" src="<?php echo esc_url(saftrade_flower_image_url(get_the_ID(),'full')); ?>" data-saf-fallback="<?php echo esc_url(saftrade_flower_placeholder_image(get_the_ID())); ?>" alt="<?php echo esc_attr(get_the_title()); ?>"><div class="saf-detail-note">Фото і відтінок є орієнтовними; фактичну партію та специфікацію підтверджують перед замовленням.</div></div><div class="saf-product-detail-copy"><div class="saf-breadcrumb"><a href="<?php echo esc_url(saftrade_catalog_url()); ?>">Каталог</a><span>/</span><?php if($terms&&!is_wp_error($terms)) echo esc_html($terms[0]->name); ?></div><h1><?php the_title(); ?></h1><p class="saf-lead"><?php echo esc_html(get_the_excerpt()); ?></p><div class="saf-spec-grid"><?php $specs=[['Походження / джерело','saf_origin'],['Сорт / клас','saf_grade'],['Пакування','saf_pack'],['Доступність','saf_availability'],['Мін. замовлення','saf_moq'],['Кольори','saf_colors'],['Довжина','saf_stem']]; foreach($specs as $spec): ?><div><span><?php echo esc_html($spec[0]); ?></span><strong><?php echo esc_html(get_post_meta(get_the_ID(),$spec[1],true) ?: ($spec[1]==='saf_origin' ? 'Уточнюється для конкретної партії' : 'За запитом')); ?></strong></div><?php endforeach; ?></div><div class="saf-entry"><?php the_content(); ?></div><div class="saf-detail-actions"><button class="saf-btn" type="button" data-saf-quote data-interest="<?php echo esc_attr(get_the_title()); ?>">Запросити ціну та наявність <span>→</span></button><a class="saf-ghost-dark" href="<?php echo esc_url(saftrade_catalog_url()); ?>">Назад до каталогу</a></div></div></div><?php endwhile; ?></div></section></main><?php get_footer(); ?>
